SP_EXTRA = [{'sub': 'What makes a story', 'focus': 'the quiet to in going to', 'skill': ('Gonna, in real speech', ['In going to the to is very small: it sounds like gunna.', 'Say I am going to read it with no stop in the middle.', 'A loud to sounds like a reading test, not a sentence.', 'In writing it is always going to. Only the sound changes.']), 'repeat': ['I am going to read it.', 'True is not enough.', 'A character wants something.', 'Something stops him and he does something about it.', 'At the end of the story he is not the same man.', 'A story is more interesting than a list of true things.', 'When you read this week, find the want first and the plot after it.'], 'theme': 'reading and the stories you like', 'frames': ['I am going to read ... .', 'My favourite character is ... , because ... .', 'I think ... is better than ... , because ... .', 'The last book I finished was ... .'], 'qs': ['First, what are you going to read this month?', 'Tell me about a character you remember. Say why.', 'Some people say a film is better than the book. Do you agree?', 'Finally, describe the best story you know in four sentences.'], 'model': [(1, 'I am going to read a book of short stories my sister gave me. There are eleven in it.'), (2, 'I remember a woman in a story. She waited twenty years for a letter. She wanted one small thing and she never got it.'), (3, 'I do not agree. A film will show you the face, but the book is the only place you get the want.'), (4, 'A man comes home after a war. Nobody in the town knows him. He says nothing for a year. Then he walks out again.')], 'selfcheck': ['I said going to as one quick piece', 'I used three field words', 'I gave a reason after my opinion']}, {'sub': 'Why a short story is shaped as it is', 'focus': 'reading a sentence out loud', 'skill': ('Where the voice goes down', ['At a full stop the voice goes down and stops. Let it.', 'At a comma it stays up: the sentence is not finished.', 'A long sentence has two or three pieces. Breathe between them.', 'This is the one skill that makes a reader sound like a reader.']), 'repeat': ['It starts late.', 'And it ends early.', 'The reader does the last piece.', 'A short story is not a small novel.', 'It begins on the day the problem starts.', 'The writer tells you nothing about the years before it.', 'The novel closes every door, and the short story opens one and walks out.'], 'theme': 'books, writing and your own reading', 'frames': ['I read ... pages a week.', 'I like the voice of ... , because ... .', 'A good ending is ... .', 'I will read more ... next year, because ... .'], 'qs': ['First, how much do you read in a week? Say what.', 'Do you like a long book or a short one? Say why.', 'Some endings leave the work to the reader. Do you like that?', 'Finally, tell me about a book you will not finish, and why.'], 'model': [(1, 'I read about sixty pages a week, and most of it is on my phone on the bus.'), (2, 'I like a short one. I can hold a whole short story in my head and I can see the shape of it.'), (3, 'I like it very much. The best ending I know gives you two answers and will not say which one it is.'), (4, 'I will not finish a long novel about a family. There are nine characters and after a hundred pages nobody wants anything.')], 'selfcheck': ['I let my voice go down at every full stop', 'I kept it up at the commas', 'I answered all four questions']}]

EXTRA = {'fieldname': 'Stories and Writing', 'fieldwhy': 'what turns a list of true things into a story, and why a short story starts late', 'fieldwords': [('character', 'a person in a story'), ('plot', 'the things that happen in a story, in order'), ('scene', 'one part of a story, in one place at one time'), ('novel', 'a long story in a book'), ('poem', 'a short piece of writing in lines'), ('reader', 'the person reading the book'), ('title', 'the name of a book or a story'), ('describe', 'to say what a thing or a person is like'), ('imagine', 'to see a thing in your head'), ('ending', 'the last part of a story'), ('voice', 'the way one writer sounds on the page'), ('chapter', 'one numbered part of a long book')], 'r4': {'sub': 'What makes a story', 'title': 'True Is Not Enough', 'skill': ('A list, then the thing the list is missing', ['A passage can start with something that is almost right.', 'Then it changes one thing and asks you to look again.', 'The change is the answer. Put your finger on it.', 'The last part usually names the machine in three or four steps.']), 'paras': ['Here is a list. A man got up. He went to work. He came home. He went to bed. Nothing in that list is a story, and you will not read it twice. But every sentence in it is true, and that is the point: true is not enough.', 'Now change one thing. A man got up, and he knew his brother was outside the door. Now every sentence in the list is interesting. Nobody has to tell you that. Why? Because the man wants something and something is in the way of it.', 'That is the whole machine, and it is very old. A character wants something. Something stops him. He does something about it. And at the end he is not the same man. A story is more interesting than a list, because nothing in a list wants anything.'], 'guided': [('How many sentences are in the first list?', ('two', 'three', 'four', 'five'), 2, 'A man got up. He went to work. He came home. He went to bed.'), ('Is anything in the list true?', ('no, none of it', 'yes, every sentence', 'only the first one', 'the writer does not say'), 1, 'But every sentence in it is true.'), ('What is the one thing the writer changes?', ('the man gets up later', 'the brother is outside the door', 'the man goes to bed first', 'the list gets longer'), 1, 'A man got up, and he knew his brother was outside the door.')], 'exam': [('Why is every sentence interesting now?', ('the list is longer', 'the man wants something and something is in the way', 'the sentences are not true', 'the brother is a character'), 1, 'Because the man wants something and something is in the way of it.'), ('How many steps are in the machine?', ('two', 'three', 'four', 'six'), 2, 'A character wants something. Something stops him. He does something about it. And at the end he is not the same man.'), ('What is the character like at the end?', ('the same man', 'not the same man', 'in the same place', 'asleep'), 1, 'And at the end he is not the same man.'), ('Why is a story more interesting than a list?', ('it is longer', 'nothing in a list wants anything', 'it is true', 'it has a title'), 1, 'A story is more interesting than a list, because nothing in a list wants anything.')], 'words': 141}, 'r5': {'sub': 'Why a short story is shaped as it is', 'title': 'It Starts Late and It Ends Early', 'skill': ('Two things set side by side', ['When a passage puts two forms together, it will keep them apart.', 'Here they are the novel and the short story. Mark both words.', 'Every later sentence belongs to one of them. Put it there.', 'A question may give you one and ask about the other.']), 'paras': ['A novel has got four hundred pages and a short story has got twelve. So a short story is not a small novel. It is a different machine, and it does a different job.', 'A novel can start with a child and finish with an old man. A short story has no room for that, so it starts late. It begins on the day the problem starts, and often in the middle of the day. The writer tells you nothing about the years before it.', 'And it ends early. A novel will tell you what happened to everybody. A short story stops at the moment the character sees something, and it leaves the rest to you. That is why the ending of a short story often feels like a door closing in another room. The reader does the last piece of the work.'], 'guided': [('How many pages has a short story got?', ('four hundred', 'twelve', 'a hundred', 'two'), 1, 'A novel has got four hundred pages and a short story has got twelve.'), ('Is a short story a small novel?', ('yes', 'no, it is a different machine', 'yes, with fewer characters', 'the writer does not say'), 1, 'So a short story is not a small novel. It is a different machine.'), ('Where does a short story begin?', ('with a child', 'on the day the problem starts', 'at the ending', 'in another room'), 1, 'It begins on the day the problem starts.')], 'exam': [('What does a novel do that a short story cannot?', ('start late', 'start with a child and finish with an old man', 'end early', 'leave the rest to you'), 1, 'A novel can start with a child and finish with an old man.'), ('What does the writer of a short story tell you about the years before?', ('everything', 'nothing', 'one chapter', 'the ending'), 1, 'The writer tells you nothing about the years before it.'), ('Where does a short story stop?', ('at the end of everybody’s life', 'at the moment the character sees something', 'in the middle of the day', 'after four hundred pages'), 1, 'A short story stops at the moment the character sees something.'), ('Who does the last piece of the work?', ('the writer', 'the character', 'the reader', 'the novel'), 2, 'The reader does the last piece of the work.')], 'words': 143}, 'l4': {'sub': 'What makes a story', 'caption': 'A short talk about stories', 'board': ['TRUE IS NOT ENOUGH', 'a character wants something', 'something stops him', 'at the end he is not the same'], 'skill': ('A speaker who tests you with an example', ['A talk can give you something and ask if it is the thing.', 'Your answer will be no. Listen for what is missing.', 'The speaker then names the parts. Write them as a short list.', 'The last line often tells you what to do with the idea.']), 'warm': [('Is a list of true things a story?', ('No, it is not.', 'In the morning.', 'Four sentences.', 'Yes, I am.'), 0, 'Is it ...? takes it is or it is not.'), ('What will the character be like at the end?', ('Not the same person.', 'In the same room.', 'Yes, he will.', 'A long novel.'), 0, 'What will ...? asks about the end of the story.')], 'script': [('Woman', 'I will give you four sentences and you will tell me if it is a story. A woman left the house. She took the bus. She got off at the hospital. She went in. Well? Most of you say no, and you are right, but ask yourselves why. Every word of it is true. What it has got no room for is a want. Add six words — she did not know if her father was still alive — and the same four sentences are a story. Nothing else changed at all. So when you read this week, find the want first. The plot is only what gets in its way.')], 'items': [('How many sentences does the speaker give?', ('two', 'three', 'four', 'six'), 2, 'I will give you four sentences.'), ('What do most of the students say?', ('yes', 'no', 'nothing', 'they ask a question'), 1, 'Most of you say no, and you are right.'), ('What has the list got no room for?', ('a character', 'a want', 'a hospital', 'a bus'), 1, 'What it has got no room for is a want.'), ('What does the speaker tell the class to find first?', ('the plot', 'the want', 'the ending', 'the title'), 1, 'So when you read this week, find the want first.')]}, 'l5': {'sub': 'Why a short story is shaped as it is', 'caption': 'A short talk about the short story', 'board': ['NOVEL AND SHORT STORY', '400 pages · 12 pages', 'starts late · ends early', 'the reader finishes it'], 'skill': ('Two forms, one talk', ['A talk that sets two forms side by side will go back and forth.', 'Two columns in your notes are faster than one long list.', 'Put every fact under the form it belongs to, as you hear it.', 'A question will often give you one form and ask about the other.']), 'warm': [('Will the writer tell you about the years before?', ('No, nothing at all.', 'Four hundred pages.', 'Yes, I will.', 'In the morning.'), 0, 'Will ...? takes will or will not.'), ('Which form is longer?', ('The novel.', 'In twelve pages.', 'Yes, it is.', 'The reader.'), 0, 'Which asks you to choose one of the two.')], 'script': [('Man', 'Students come to me and say, I am going to write a short story, and then they write the first chapter of a novel. The two forms are not the same size of the same thing. A novel has got room to grow a character from a child. Twelve pages have got no room at all, so a short story starts on the worst day of somebody’s life and it starts in the middle of that day. And it will stop before you want it to. The novel closes every door. The short story opens one and walks out of the room, and you are the one still standing there.')], 'items': [('What do students say to the speaker?', ('they are going to write a novel', 'they are going to write a short story', 'they will not write anything', 'they want a chapter'), 1, 'Students come to me and say, I am going to write a short story.'), ('What do they write instead?', ('a poem', 'the first chapter of a novel', 'twelve pages', 'nothing'), 1, 'Then they write the first chapter of a novel.'), ('When does a short story start?', ('when the character is a child', 'on the worst day of somebody’s life', 'at the ending', 'after twelve pages'), 1, 'A short story starts on the worst day of somebody’s life.'), ('What does the short story do with the doors?', ('it closes every door', 'it opens one and walks out', 'it leaves them all shut', 'it has no doors'), 1, 'The novel closes every door. The short story opens one and walks out of the room.')]}, 'w4': {'sub': 'Why a short story is shaped as it is', 'skill': ('Questions about what comes next', ['Will goes in front of the person: Will you read it?', 'Going to needs am, is or are: Is she going to write a novel?', 'A question word goes first: What will the reader do?', 'The verb after will and after to never changes.']), 'guided': [('The reader will do the last piece of the work.', ['what', 'will', 'the reader', 'do', 'at the end', 'of the story'], 'What will the reader do at the end of the story?'), ('She is going to write a short story.', ['is', 'she', 'going to', 'write', 'a short story', 'this term'], 'Is she going to write a short story this term?')], 'exam': [('The writer will tell you nothing about the years before.', ['will', 'the writer', 'tell', 'us', 'about the years', 'before'], 'Will the writer tell us about the years before?'), ('The story is going to stop early.', ['when', 'is', 'the story', 'going to', 'stop', 'in this chapter'], 'When is the story going to stop in this chapter?'), ('A short story is more interesting than a list.', ['why', 'is', 'a short story', 'more interesting', 'than', 'a list'], 'Why is a short story more interesting than a list?'), ('They are going to read the novel in two weeks.', ['how long', 'are', 'they', 'going to', 'take', 'over the novel'], 'How long are they going to take over the novel?')]}, 'w5': {'sub': 'What makes a story', 'prof': 'Dr Dale', 'target': 85, 'question': 'Your college is going to put one book on every first-year reading list. Some people want a novel and some want a book of short stories. Which do you think is better for a first year, and why?', 'posts': [('Ana', 'w', 'Short stories, and it is not a hard choice. A first-year student can finish one in an evening and come to class with the whole thing in her head. Nobody finishes a four-hundred-page novel in week two.'), ('Mei', 'w', 'But a novel is the harder and the better lesson. You learn to hold a character for four hundred pages. Twelve pages will not teach anybody that, and the exam is a long paper.')], 'skill': ('A choice with a reason on each side', ['Both answers are good, so your reason is the whole mark.', 'Say which one, then say what the other one does better.', 'Use the passage: the two forms are different machines.', 'Eighty-five words is about eight sentences.']), 'starters': ['I agree with Ana, because ...', 'Mei is right that ...', 'The passage says the two forms ...', 'So the college must ...'], 'model': ['I agree with Ana for a first year. A student with no finished book learns nothing, and twelve pages get read.', 'Mei is right that a novel teaches something a short story cannot. The passage says they are different machines, so they are different lessons.', 'But the first year is the year to build the habit. Start with short stories in the first term and put the novel in the second. By then the students will read four hundred pages and not be afraid of them.'], 'model_words': 86}}
